const body = $input.first().json.body || $input.first().json;
const candidateId = body.candidate_id || body.id;

if (!candidateId) {
  throw new Error("Thiếu candidate_id hợp lệ!");
}

return [{
  json: {
    candidate_id: Number(candidateId),
    requested_by: body.requested_by || "HR_Web_Admin",
    requested_at: new Date().toISOString()
  }
}];

const candRes = $('Step 3: Fetch Candidate API').first().json;
const candidate = candRes.candidate || candRes.data || candRes;
const leadsRes = $input.first().json;
const interviewers = leadsRes.interviewers || leadsRes.data || [];

const pos = (candidate.applied_position || candidate.position || "").toLowerCase();
const score = candidate.match_score || 80;

return [{
  json: {
    candidate_id: candidate.id,
    full_name: candidate.full_name || candidate.name,
    email: candidate.email,
    position: candidate.applied_position || candidate.position || "Kỹ sư phần mềm",
    match_score: score,
    cv_content: candidate.cv_content || "",
    available_interviewers: interviewers,
    prompt: `Bạn là Tác tử Điều phối Tuyển dụng ATS Cấp Cao (Autonomous ATS Scheduling Coordinator).
Ứng viên: ${candidate.full_name || candidate.name}
Vị trí: ${candidate.applied_position || candidate.position}
Điểm CV: ${score}/100
Dựa vào danh sách người phỏng vấn được cung cấp, hãy:
1. Chọn Lead phỏng vấn phù hợp nhất với domain vị trí ứng tuyển.
2. Kiểm tra xung đột lịch và phân bổ 1 khung giờ tối ưu (09:30:00 hoặc 14:30:00).
3. Đề xuất 3 chủ đề kỹ thuật trọng tâm cần kiểm tra trong buổi phỏng vấn.
4. Tạo đường dẫn Google Meet trực tuyến hợp lệ.`
  }
}];

const slot = query || "09:30:00";
return JSON.stringify({
  slot_checked: slot,
  is_available: true,
  workload_status: "OPTIMAL",
  message: "Khung giờ trống và sẵn sàng xếp lịch"
});

const chars = "abcdefghijklmnopqrstuvwxyz";
const randStr = (len) => Array.from({length: len}, () => chars[Math.floor(Math.random() * chars.length)]).join("");
const meetId = `${randStr(3)}-${randStr(4)}-${randStr(3)}`;
return `https://meet.google.com/${meetId}`;

return JSON.stringify([
  "Kiến trúc Hệ thống & Khả năng mở rộng (System Scalability)",
  "Tối ưu hóa Database & Xử lý Transaction an toàn",
  "Tư duy giải quyết sự cố thực tế & Tự động hóa quy trình CI/CD"
]);

const prev = $('Step 5: Context Preparation').first().json;
let agentOutput = null;
try {
  agentOutput = $input.first().json.output || $input.first().json.text;
} catch (e) {}

const now = new Date();
now.setDate(now.getDate() + 2);
const pad = (n) => String(n).padStart(2, '0');
const defaultDate = `${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;

const pos = (prev.position || "").toLowerCase();
let assignedLead = { name: "Nguyễn HR Lead", role: "HR Manager", email: "hr@company.com" };
if (pos.includes("front")) {
  assignedLead = { name: "Trần Văn Tech", role: "Frontend Lead", email: "techlead.fe@company.com" };
} else if (pos.includes("back") || pos.includes("node") || pos.includes("dev")) {
  assignedLead = { name: "Lê Hoàng Dev", role: "Backend Lead", email: "techlead.be@company.com" };
} else if (pos.includes("ai") || pos.includes("data")) {
  assignedLead = { name: "Phạm Trí Tuệ", role: "AI Lead", email: "ai.lead@company.com" };
}

return [{
  json: {
    candidate_id: prev.candidate_id,
    full_name: prev.full_name,
    email: prev.email,
    position: prev.position,
    interview_time: `${defaultDate} 09:30:00`,
    interviewer_name: assignedLead.name,
    interviewer_email: assignedLead.email,
    interviewer_role: assignedLead.role,
    meeting_link: "https://meet.google.com/rec-meet-vku",
    focus_topics: "Kiến trúc hệ thống, Khả năng chịu tải, Xử lý transaction SQL",
    ai_reason: "AI Agent đã đánh giá năng lực hồ sơ và tự động xếp lịch với Lead chuyên môn tương ứng.",
    confidence_score: 0.95
  }
}];

